// Auto-generated email asset. The Setu logo (white, transparent) used in the
// navbar, downscaled to 96x96 and base64-encoded so it can be embedded as an
// inline CID attachment in transactional emails. CID attachments render
// reliably across Gmail/Outlook/Apple Mail without depending on a public URL.
export const SETU_LOGO_CID = "setu-logo";

export const SETU_LOGO_BASE64 =
  "";

/** Nodemailer inline attachment for the Setu logo (reference via cid:setu-logo). */
export const setuLogoAttachment = {
  filename: "setu-logo.png",
  content: Buffer.from(SETU_LOGO_BASE64, "base64"),
  cid: SETU_LOGO_CID,
  contentType: "image/png",
};
